  # Determine badge gradient based on score
  $badgeGrad = "var(--grad-green)"
  $badgeShadow = "rgba(67,160,71,0.45)"
  if ($score -lt 50) {
    $badgeGrad = "var(--grad-red)"
    $badgeShadow = "rgba(229,57,53,0.45)"
  } elseif ($score -lt 75) {
    $badgeGrad = "var(--grad-yellow)"
    $badgeShadow = "rgba(239,108,0,0.45)"
  }

  # Dim data with max scores
  $dimData = @(
    @{Label="变化天花板"; Val=$dims["变化"]; Max=18},
    @{Label="终局时机"; Val=$dims["终局"]; Max=17},
    @{Label="需求真伪"; Val=$dims["需求"]; Max=17},
    @{Label="方案优劣"; Val=$dims["方案"]; Max=17},
    @{Label="商业模型"; Val=$dims["商模"]; Max=16},
    @{Label="增长壁垒"; Val=$dims["壁垒"]; Max=15},
    @{Label="风险扣分"; Val=$dims["风险"]; Max=10}
  )

  $dimHtml = ""
  foreach ($d in $dimData) {
    $val = $d.Val
    $max = $d.Max
    $label = $d.Label
    $isRisk = $label -eq "风险扣分"
    $absVal = [Math]::Abs($val)
    $pct = 0
    if ($max -gt 0) { $pct = [Math]::Round(($absVal / $max) * 100) }
    if ($pct -gt 100) { $pct = 100 }

    $fillClass = "fill-green"
    if ($isRisk) {
      $fillClass = "fill-red"
      $scoreText = "$val/$max"
    } else {
      if ($val -ge 12) { $fillClass = "fill-green" }
      elseif ($val -ge 7) { $fillClass = "fill-yellow" }
      else { $fillClass = "fill-red" }
      $scoreText = "$val/$max"
    }

    $dimHtml += @"
  <div class="dim-item">
    <span class="dim-label">$label</span>
    <div class="dim-bar-wrap">
      <div class="dim-bar"><div class="fill $fillClass" style="width:${pct}%"></div></div>
      <span class="dim-score">$scoreText</span>
    </div>
  </div>
"@
  }

  # M status helper
  function MBadge($m) {
    if ($m -eq "🟢") { return '<span class="tag tag-green">🟢 通过</span>' }
    elseif ($m -eq "🟡") { return '<span class="tag tag-yellow">🟡 有条件通过</span>' }
    else { return '<span class="tag tag-red">🔴 未通过</span>' }
  }
  $m1b = MBadge $m1; $m2b = MBadge $m2; $m3b = MBadge $m3
  $m4b = MBadge $m4; $m5b = MBadge $m5; $m6b = MBadge $m6

  # Cards count badge color
  $cardsNum = [int]($cards.Split("/")[0])
  $cardsColor = "tag-green"
  if ($cardsNum -ge 8) { $cardsColor = "tag-red" }
  elseif ($cardsNum -ge 5) { $cardsColor = "tag-yellow" }

  # Assumptions
  $assumeHtml = ""
  if ($p0 -gt 0) {
    $assumeHtml += @"
    <div class="assumption-item">
      <div class="ai-prio p0">P0</div>
      <div class="ai-text">
