<div class="container">

<!-- ===== Hero Header ===== -->
<div class="hero">
  <div class="hero-code">五步法深度分析 &middot; $code</div>
  <div class="hero-badge-wrap">
    <div class="hero-badge">
      <span class="num">$score</span>
      <span class="unit">总分</span>
    </div>
  </div>
  <div class="hero-title">$name</div>
  <div class="hero-sub">中建发展AI硬件方向</div>
  <div class="hero-judgment">
    <span style="font-size:16px;">$jEmoji</span> $judgment
  </div>
</div>

<!-- ===== Dimension Score Strip ===== -->
<div class="dim-strip">
  <div class="dim-strip-title">七维评分 &middot; 各维度表现</div>
$dimHtml
</div>

<!-- ===== Content ===== -->
<div class="content">

  <!-- ===== 预判摘要 ===== -->
  <div class="card">
    <h2><span class="emoji-box" style="background:var(--green-bg);color:var(--green);">&#x1F4CB;</span> 预判摘要</h2>
    <div class="summary-box amber-border">
      <div class="sb-row">
        <span class="sb-label">20张硬伤卡牌评分</span>
        <span><span class="tag $cardsColor">$cards 命中</span></span>
      </div>
      <div class="sb-row">
        <span class="sb-label">整体判定</span>
        <span class="verdict-badge $jc">$verdictText</span>
      </div>
      <div class="sb-row">
        <span class="sb-label">推进优先级</span>
        <span><span class="tag $tierTag">$tier</span></span>
      </div>
    </div>
    <p><strong>一句话结论：</strong>$oneLine</p>
  </div>

  <!-- ===== 行业预判六模块 ===== -->
  <div class="card">
    <h2><span class="emoji-box" style="background:var(--blue-50);color:var(--blue);">&#x1F3F0;</span> 行业预判六模块</h2>
    <div class="tbl-wrap">
      <table>
        <tr><th>模块</th><th>名称</th><th>结果</th></tr>
        <tr><td>M1</td><td>拆解行业</td><td>$m1b</td></tr>
        <tr><td>M2</td><td>洞察变化</td><td>$m2b</td></tr>
        <tr><td>M3</td><td>预判稳态</td><td>$m3b</td></tr>
        <tr><td>M4</td><td>Timing时机</td><td>$m4b</td></tr>
        <tr><td>M5</td><td>天花板大小</td><td>$m5b</td></tr>
        <tr><td>M6</td><td>集中度</td><td>$m6b</td></tr>
      </table>
    </div>
  </div>

  <!-- ===== 推进建议 ===== -->
  <div class="card">
    <h2><span class="emoji-box" style="background:var(--green-bg);color:var(--green);">&#x25B6;&#xFE0F;</span> 推进建议</h2>
    <div class="action-card">
      <div class="ac-title">核心建议</div>
      <div class="ac-desc">$summary</div>
    </div>
  </div>

  <!-- ===== 关键假设 ===== -->
  <div class="card">
    <h2><span class="emoji-box" style="background:#eef2ff;color:#4338ca;">&#x1F9EA;</span> 关键假设清单</h2>
    <div class="summary-strip">
      <span class="strip-label">总计</span>
      <div class="strip-bar"><div class="strip-fill" style="width:$(($p0+$p1+$p2)*10)%;background:var(--grad-yellow);"></div></div>
      <span class="strip-val" style="color:var(--amber);">$($p0+$p1+$p2) 项</span>
    </div>
$assumeHtml
  </div>

  <!-- ===== 风险提示 ===== -->
  <div class="card">
    <h2><span class="emoji-box" style="background:var(--amber-bg);color:var(--amber);">&#x1F4A5;</span> 风险提示 &middot; 硬伤卡牌</h2>
    <div class="summary-strip">
      <span class="strip-label">命中数</span>
      <div class="strip-bar"><div class="strip-fill" style="width:$($cardsNum*5)%;background:$(if($cardsNum -ge 8){'var(--grad-red)'}elseif($cardsNum -ge 5){'var(--grad-yellow)'}else{'var(--grad-green)'});"></div></div>
      <span class="strip-val" style="color:$(if($cardsNum -ge 8){'var(--red)'}elseif($cardsNum -ge 5){'var(--amber)'}else{'var(--green)'});">$cards</span>
    </div>
    <ul class="check-list">
$riskCards
    </ul>
  </div>

</div>

<!-- ===== Footer ===== -->
<div class="footer">
  <p>分析引擎：一堂五步法 x 20张硬伤卡牌 &middot; 2026-06-15</p>
  <p class="brand">中建发展AI硬件方向</p>
</div>

</div>
</body>
</html>
